// Prefixed with `_` so Astro does not treat this file as a route.
// Shared with the client, so keep it free of runtime imports.
import type { UsageCall } from "../../../components/ui/usage-breakdown";

export type Belief = {
  id: string;
  slug: string;
  title: string;
  concept: string;
};
export type Post = { id: string; title: string; uri: string; excerpt: string };
export type Rephrasing = {
  /** 01 YOUR QUESTION, generated by AI */
  question: string;
  /** 02 A DIFFERENT VIEW, generated by AI */
  reframe: string;
  beliefs: Belief[];
  /** Model usage per call. Development only: it exposes models and costs. */
  calls?: UsageCall[];
};

/** The posts route response, one list per result section. */
export type Results = {
  /** 04 HOW CHANGE HAPPENS */
  methods: Post[];
  /** 05 IN THE REAL WORLD */
  projects: Post[];
  /** 06 AN UNEXPECTED CONNECTION */
  unexpected: Post[];
};

export const MAX_TEXT_LENGTH = 200;
